UPDATE businesses SET description = 'Capitec Bank Nyanga Junction is the Capitec branch at Shop 28 in Nyanga Junction Shopping Centre on Duinefontein Road, where Manenberg borders Gugulethu. It is a busy local branch for residents of Manenberg, Gugulethu, Nyanga and the surrounding Cape Flats communities.

Customers can open a savings account, apply for a personal loan, look at Capitec’s insurance products and take care of everyday transactions with the help of branch consultants. Capitec is known for simple, affordable banking with clear fees, and the branch makes good use of the bank’s app and self-service technology to keep visits short. A 24-hour ATM next to the branch lets customers draw cash safely outside branch hours. Being inside one of the area’s main shopping centres, it is easy to sort out banking during a regular shopping trip. Capitec Bank is at Shop 28, Nyanga Junction Shopping Centre, Duinefontein Road, Manenberg.', description_enriched_at = datetime('now') WHERE slug = 'capitec-bank-nyanga-junction-manenberg' AND description = 'A Capitec Bank branch inside Nyanga Junction shopping centre, Manenberg, offering standard retail banking services.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
